-- The tester comment moves from the step to the evidence it belongs to, and gains
-- a `collected` flag: when the tester sets it, a manual evidence that has nothing to
-- attach (for example user names are generated by the system, so no variant can be
-- registered) counts as collected from the comment alone. Kept apart from evidence
-- versions and step verdicts, so resetting a step or a test keeps it. A row with an
-- empty comment and collected = 0 is removed. The old per-step table is dropped; its
-- comments (only used so far on WSTG-IDNT-05 in development) are not migrated.
CREATE TABLE evidence_comments (
    target_id   INTEGER NOT NULL REFERENCES targets (id) ON DELETE CASCADE,
    evidence_id TEXT    NOT NULL,
    comment     TEXT    NOT NULL DEFAULT '',
    collected   INTEGER NOT NULL DEFAULT 0,   -- 1 = tester marks the evidence satisfied by the comment
    updated_at  TEXT    NOT NULL,
    updated_by  TEXT    NOT NULL,
    PRIMARY KEY (target_id, evidence_id)
);

DROP TABLE IF EXISTS step_comments;
